with parsed as (select id, effective_from, discounts, aggregate(tier_prices, 0D, (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, element_at(tier_prices, 1) as entry_price from price_tiers) select case when entry_price >= 27 then 'PREMIUM' else 'STANDARD' end as entry_price_tier, percentile_approx(avg_tier_price, array(0.25, 0.5, 0.75)) as avg_tier_price_quartiles, approx_percentile(entry_price, array(0.25, 0.5, 0.75)) as entry_price_quartiles, approx_percentile(entry_price, array(0.25, 0.5, 0.75)) as entry_price_quartiles_2, round(avg(entry_price), 2) as avg_entry_price from parsed group by case when entry_price >= 27 then 'PREMIUM' else 'STANDARD' end;
